Analyze this React component for performance anti-patterns, unnecessary re-renders, and potential bugs. Refactor using hooks best practices:
```jsx
function UserDashboard({ userId }) {
  const [user, setUser] = useState(null);
  const [posts, setPosts] = useState([]);
  useEffect(() => {
    fetch(`/api/users/${userId}`).then(r => r.json()).then(setUser);
    fetch(`/api/users/${userId}/posts`).then(r => r.json()).then(setPosts);
  });
  const total = posts.reduce((acc, p) => acc + p.likes, 0);
  return <div>{user?.name} - {total} likes</div>;
}
```
